type Fact={focus:string;candidates:readonly (readonly [string,boolean])[]};
const expect=(focus:string,phrases:readonly string[],trueAt:number):Fact=>
  ({focus,candidates:phrases.map((phrase,i)=>[phrase,i===trueAt])});
const rounding=['切上げ','切捨て','けた上げ','正規化'];
const sortMechanisms=['整列済みのデータ列の正しい位置','データ中の最小値','基準値を選び','隣り合ったデータの比較'];
const cells=['コンデンサに電荷','製造時にデータ','紫外線照射で消去','フリップフロップ'];
const discWays=['ディスクアットワンス','ディスクキャッシュ','ディスクストライピング','ディスクミラーリング'];
const transfer=[
  '変更があるものを，置換時に主記憶に書き込む',
  '読み取った磁気ディスクのデータを主記憶に保持',
  'キャッシュ側と主記憶側の双方に伝える',
  '主記憶を幾つかの区画に分割',
];
export const knowledgeFacts:Record<number,readonly Fact[]>={
  // 正規化は指数と仮数を同時に調整、切上げと切捨てはけたを減らす、けた上げは加算。
  4:[
    expect('仮数部の表現方法は，絶対値表現',rounding,3),
    expect('元の値以上で最も小さい値',rounding,0),
    expect('残す側の値を増やさない',rounding,1),
    expect('次の上位のけたに1を渡す',rounding,2),
  ],
  // 基準値分割、整列部分への挿入、極値の選択、隣接交換の対応。
  13:[
    expect('クイックソート',sortMechanisms,2),expect('挿入ソート',sortMechanisms,0),
    expect('選択ソート',sortMechanisms,1),expect('バブルソート',sortMechanisms,3),
  ],
  // 保持要素、製造時の記録、紫外線の消去、ラッチの動作。
  16:[
    expect('DRAMの説明',cells,0),expect('マスクROMの説明',cells,1),
    expect('紫外線消去型EPROMの説明',cells,2),expect('SRAMの説明',cells,3),
  ],
  // 通知の発信元と、実行命令に起因する同期例外を分ける。
  20:[
    expect('外部割込みが発生',[
      '主記憶に存在しないページへのアクセス','システムコール命令の実行','ゼロによる除算','入出力動作の終了',
    ],3),
    expect('I/O制御器はCPUへ受信完了を通知',[
      'I/O制御器からの受信完了','未実装の命令コード','ページ違反','明示的なシステムコール',
    ],0),
    expect('内部割込みが発生',[
      'ディスク装置の転送完了','キーボード装置による入力到着','禁止されたメモリ領域への命令によるアクセス','タイマ装置の満了',
    ],2),
    expect('機械語命令から独立に発生',[
      'オペランドのアクセス違反','機械語の例外を発生させるシステムコール','タイマからの周期的な通知','存在しないページへのアクセス',
    ],2),
  ],
  // ライトバックは変更済みの置換、ライトスルーは書込み時の反映、ハードウェア管理のミスは下位層から取得。
  21:[
    expect('キャッシュメモリに関する記述',[
      '主記憶の書換えはブロックの入替え時','実記憶と仮想記憶のメモリ容量の差','ヒットしないと割込みが生じ','必要性は減っている',
    ],0),
    expect('ライトスルー方式',[
      '置き換えるまで，主記憶には書き込まない','主記憶側へも伝える','必ず仮想記憶ページをディスクに退避','書込みに関する処理は行わない',
    ],1),
    expect('ライトバック方式',[
      '主記憶には変更前のデータを残す','常にディスクだけへ書く','変更があったブロックの内容を主記憶側へ書き戻す','古いブロックを書き直す',
    ],2),
    expect('通常のハードウェア管理',[
      '割込みを発生させて，ユーザープログラムに転送','ページ全体をスワップアウト','主記憶側にも存在しないと判断','下位層からデータを取得',
    ],3),
  ],
  // 番地を独立バンクへ分割する方式と、キャッシュが送る内容・記憶階層の区別。
  23:[
    expect('メモリインタリーブ',[
      '不要になった情報を主記憶に書き込む','磁気ディスクのアクセス時間とのギャップ','同時にキャッシュメモリの更新','幾つかの区画に分割',
    ],3),
    expect('ライトバック方式',transfer,0),expect('ライトスルー方式',transfer,2),expect('磁気ディスクの読取りキャッシュ',transfer,1),
  ],
  // 連続記録、読取り結果の保持、分散配置、冗長コピーを別の目的で判定。
  25:[
    expect('セクタ単位で分散配置',discWays,2),expect('複数の磁気ディスクに複製',discWays,3),
    expect('高速なメモリに一時保持',discWays,1),expect('全トラックを一つの連続した書込み',discWays,0),
  ],
};
